solution.solution.cpp:
int largestOfThree(int a, int b, int c)
{
    int largest{ a };
    if (b > largest)
    {
        largest = b;
    }
    if (c > largest)
    {
        largest = c;
    }
    return largest;
}

unitTests:
TEST("largest first") { CHECK_EQ(largestOfThree(9, 4, 2), 9); }
TEST("largest in the middle") { CHECK_EQ(largestOfThree(1, 8, 3), 8); }
TEST("largest last") { CHECK_EQ(largestOfThree(1, 2, 7), 7); }
TEST("ties and negatives") { CHECK_EQ(largestOfThree(5, 5, 5), 5); CHECK_EQ(largestOfThree(-9, -2, -4), -2); }

